import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv3d_t_cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define THREADS 128

__device__ __forceinline__ int get_stride_index(int dim, int kernel, int stride, int padding, int dilation) {
    return (dim - kernel * dilation + padding) / stride;
}

__global__ void conv_transpose3d_kernel(
    const float* input, const float* weight, const float* bias,
    float* output,
    int batch_size, int in_channels, int out_channels,
    int kernel_size, int stride, int padding, int output_padding, int dilation, int groups,
    int input_depth, int input_height, int input_width,
    int output_depth, int output_height, int output_width
) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch_size * out_channels * output_depth * output_height * output_width) return;

    const int b = idx / (out_channels * output_depth * output_height * output_width);
    const int rem = idx % (out_channels * output_depth * output_height * output_width);
    const int oc = rem / (output_depth * output_height * output_width);
    const int d = (rem % (output_depth * output_height * output_width)) / (output_height * output_width);
    const int h = (rem % (output_height * output_width)) / output_width;
    const int w = rem % output_width;

    float val = 0.0f;
    const int group_size = in_channels / groups;
    const int group = oc / (out_channels / groups);

    for (int ic = group * group_size; ic < (group+1)*group_size; ++ic) {
        for (int kd = 0; kd < kernel_size; ++kd) {
            for (int kh = 0; kh < kernel_size; ++kh) {
                for (int kw = 0; kw < kernel_size; ++kw) {
                    const int input_d = (d + padding - kd * dilation) / stride;
                    const int input_h = (h + padding - kh * dilation) / stride;
                    const int input_w = (w + padding - kw * dilation) / stride;

                    if (input_d * stride != (d + padding - kd * dilation) ||
                        input_h * stride != (h + padding - kh * dilation) ||
                        input_w * stride != (w + padding - kw * dilation)) continue;

                    if (input_d < 0 || input_d >= input_depth ||
                        input_h < 0 || input_h >= input_height ||
                        input_w < 0 || input_w >= input_width) continue;

                    const int input_idx = ((b * in_channels + ic) * input_depth + input_d) * input_height * input_width 
                                        + input_h * input_width + input_w;

                    const int weight_idx = ((oc * (in_channels / groups) + (ic % group_size)) * kernel_size + kd) 
                                        * kernel_size * kernel_size + kh * kernel_size + kw;

                    val += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }

    if (bias) val += bias[oc];

    output[idx] = val;
}

torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
    int kernel_size, int stride, int padding, int output_padding, int dilation, int groups
) {
    const auto in_sizes = input.sizes();
    const int batch_size = in_sizes[0];
    const int in_channels = in_sizes[1];
    const int input_depth = in_sizes[2];
    const int input_height = in_sizes[3];
    const int input_width = in_sizes[4];
    const int out_channels = weight.size(0);

    const int output_depth = (input_depth - 1) * stride - 2 * padding + dilation * (kernel_size - 1) + output_padding + 1;
    const int output_height = (input_height - 1) * stride - 2 * padding + dilation * (kernel_size - 1) + output_padding + 1;
    const int output_width = (input_width - 1) * stride - 2 * padding + dilation * (kernel_size - 1) + output_padding + 1;

    auto output = torch::empty({batch_size, out_channels, output_depth, output_height, output_width}, input.options());

    const int total_elements = batch_size * out_channels * output_depth * output_height * output_width;
    const dim3 blocks((total_elements + THREADS - 1) / THREADS);

    conv_transpose3d_kernel<<<blocks, THREADS>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size, in_channels, out_channels,
        kernel_size, stride, padding, output_padding, dilation, groups,
        input_depth, input_height, input_width,
        output_depth, output_height, output_width
    );

    return output;
}
"""

conv3d_t_cpp = """
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
    int kernel_size, int stride, int padding, int output_padding, int dilation, int groups);
"""

conv3d_t_ext = load_inline(
    name="conv3d_t_ext",
    cpp_sources=conv3d_t_cpp,
    cuda_sources=conv3d_t_cuda_source,
    functions=["conv_transpose3d_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, 
                 output_padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.dilation = dilation
        self.groups = groups

        self.weight = nn.Parameter(torch.empty(
            out_channels,
            in_channels // groups,
            kernel_size,
            kernel_size,
            kernel_size
        ))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.bias = None

        nn.init.kaiming_uniform_(self.weight, a=5**0.5)
        if self.bias is not None:
            nn.init.zeros_(self.bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return conv3d_t_ext.conv_transpose3d_cuda(
            x, 
            self.weight, 
            self.bias if self.bias is not None else torch.tensor([]).to(x.device),
            self.kernel_size,
            self.stride,
            self.padding,
            self.output_padding,
            self.dilation,
            self.groups
        )
